assert OLD_TICK.count("public void tick(@PKG@.PetReel rl)") == 1 and OLD_TICK.count("public void run()") == 1 and OLD_TICK.count("M(") == 2, "0.4.15 tick + run"
NEW_TICK = r'''# 0.4.16: the end of a roll in ONE place - the result card (one rebuild) + the reveal line; never throws
M(HPAGE, r"""
public void finish(String why) {
  this.gen = this.gen + 1L;
  this.view = 2;
  this.due = 0L;
  this.info = "+You hatched a " + @PKG@.PetKind.rarityName(this.prar) + " " + @PKG@.PetEgg.kindName(this.kind) + "!";
  try { rebuild(); } catch (Throwable t) { @PKG@.PetsLog.warnOnce("reelend:" + t.getClass().getName(), "the hatch result could not be drawn (" + why + "): " + t); }
  reveal();
}""")
# 0.4.16: the player's CURRENT world (field reads only - safe off the world thread); the world cached at the start is the fallback
M(HPAGE, r"""
public @WLD@ worldNow() {
  try {
    @REF@ ref = this.playerRef.getReference();
    if (ref != null && ref.isValid()) {
      @WLD@ w = @PKG@.PetsEng.worldObj(ref.getStore());
      if (w != null) return w;
    }
  } catch (Throwable t) { }
  return this.w;
}""")
M(HPAGE, r"""
public boolean hop(@PKG@.PetReel rl) {
  @WLD@ w = worldNow();
  if (w != null && @PKG@.PetWorld.execute(w, rl)) return true;
  return this.w != null && this.w != w && @PKG@.PetWorld.execute(this.w, rl);
}""")
# 0.4.16: the roll's own length = the frame delays + both holds (the tick's exact schedule)
M(HPAGE, r"""
public long expectMs() {
  long t = 0L;
  for (int f = 0; f < this.f1 - 1; f++) t = t + delay(1, f, this.f1);
  for (int f = 0; f < this.f2 - 1; f++) t = t + delay(2, f, this.f2);
  return t + 2L * (long) @PKG@.PetEggDefs.HOLD_MS;
}""")
# 0.4.16 THE WATCHDOG: one task per roll at its length + pets.hatch.stallSeconds; it finishes a roll that is still spinning then
M(HPAGE, r"""
public void armDog() {
  int s = @PKG@.PetsCfg.STALL_S < 1 ? 1 : (@PKG@.PetsCfg.STALL_S > 60 ? 60 : @PKG@.PetsCfg.STALL_S);
  long ms = expectMs() + 1000L * (long) s;
  this.due = System.currentTimeMillis() + ms;
  @PKG@.PetReel d = new @PKG@.PetReel(this, this.gen, ms);
  d.dog = true;
  d.later();
}""")
M(HPAGE, r"""
public void watch(@PKG@.PetReel rl) {
  if (rl == null || rl.gen != this.gen || this.view != 1) return;
  if (!current()) { this.gen = this.gen + 1L; reveal(); return; }
  STALLS = STALLS + 1L;
  @PKG@.PetsLog.warnOnce("reelstall", "a hatch reel stopped before its end - the result was shown after pets.hatch.stallSeconds (the hatch itself was saved)");
  finish("stall");
}""")
# ONE frame on the world thread (0.4.15's tick body; 0.4.16: every way out that is not the next frame = finish())
M(HPAGE, r"""
public void step() {
  if (!current()) { this.gen = this.gen + 1L; reveal(); return; }
  if (this.due > 0L && System.currentTimeMillis() > this.due) { STALLS = STALLS + 1L; finish("late"); return; }
  java.util.UUID u = this.playerRef.getUuid();
  long next = 0L;
  if (this.phase <= 1) {
    this.phase = 1;
    if (this.frame < this.f1 - 1) {
      this.frame = this.frame + 1;
      if (this.frame % 2 == 0) @PKG@.PetSnd.play(u, @PKG@.PetSnd.pick(@PKG@.PetsCfg.SND_ON, @PKG@.PetsCfg.SND_REEL, @PKG@.PetsCfg.SND_REEL_ID), "reel" + this.frame);
      next = delay(1, this.frame, this.f1);
      if (this.frame == this.f1 - 1) { @PKG@.PetSnd.play(u, @PKG@.PetSnd.pick(@PKG@.PetsCfg.SND_ON, @PKG@.PetsCfg.SND_REVEAL, @PKG@.PetsCfg.SND_REVEAL_ID), "reveal1"); next = (long) @PKG@.PetEggDefs.HOLD_MS; }
    } else { this.phase = 2; this.frame = 0; next = delay(2, 0, this.f2); }
  } else {
    if (this.frame < this.f2 - 1) {
      this.frame = this.frame + 1;
      if (this.frame % 2 == 0) @PKG@.PetSnd.play(u, @PKG@.PetSnd.pick(@PKG@.PetsCfg.SND_ON, @PKG@.PetsCfg.SND_REEL, @PKG@.PetsCfg.SND_REEL_ID), "reelb" + this.frame);
      next = delay(2, this.frame, this.f2);
      if (this.frame == this.f2 - 1) { @PKG@.PetSnd.play(u, @PKG@.PetSnd.pick(@PKG@.PetsCfg.SND_ON, @PKG@.PetsCfg.SND_REVEAL, @PKG@.PetsCfg.SND_REVEAL_ID), "reveal2"); next = (long) @PKG@.PetEggDefs.HOLD_MS; }
    } else {
      finish("end");
      return;
    }
  }
  try {
    @UCB@ b = new @UCB@();
    if (this.phase == 1) drawReel(b, 1, this.frame);
    else { drawReel(b, 1, this.f1 - 1); drawReel(b, 2, this.frame); }
    sendUpdate(b);
    FRAMES = FRAMES + 1L;
  } catch (Throwable t) { @PKG@.PetsLog.warnOnce("reelframe:" + t.getClass().getName(), "a hatch reel frame failed (the result is shown): " + t); next = -1L; }
  if (next < 0L) { finish("frame"); return; }
  @PKG@.PetReel nx = new @PKG@.PetReel(this, this.gen, next);
  nx.page = this;
  if (!nx.later()) finish("schedule");
}""")
M(HPAGE, r"""
public void tick(@PKG@.PetReel rl) {
  if (rl == null || rl.gen != this.gen || this.view != 1) return;
  try { step(); }
  catch (Throwable t) {
    @PKG@.PetsLog.warnOnce("reeltick:" + t.getClass().getName(), "a hatch reel step failed (the result is shown): " + t);
    if (this.view == 1) finish("error");
  }
}""")
M(HREEL, r"""
public void run() {
  try {
    if (this.page == null) return;
    if (!this.onWorld) {
      this.onWorld = true;
      if (!this.page.hop(this)) {
        this.page.gen = this.page.gen + 1L;
        @PKG@.PetsLog.warnOnce("reelhop", "a hatch reel could not reach the player's world (the page shows the result on the next click; the chat line comes within 30 s)");
      }
      return;
    }
    if (this.dog) this.page.watch(this);
    else this.page.tick(this);
  } catch (Throwable t) { @PKG@.PetsLog.warnOnce("reel:" + t.getClass().getName(), "a hatch reel failed: " + t); }
}""")
'''
